package com.orderflow.delivery.security;import com.fasterxml.jackson.databind.ObjectMapper;import com.orderflow.delivery.correlation.DeliveryRequestAttributes;import com.orderflow.platform.error.*;import com.orderflow.platform.http.CorrelationHeaders;import jakarta.servlet.http.*;import java.io.IOException;import java.time.Instant;import java.util.List;import org.springframework.http.*;import org.springframework.stereotype.Component;@Component public class ApiSecurityErrorWriter{private final ObjectMapper mapper;public ApiSecurityErrorWriter(ObjectMapper m){mapper=m;}public void write(HttpServletRequest q,HttpServletResponse p,HttpStatus s,ErrorCode c,String message)throws IOException{if(p.isCommitted())return;String id=(String)q.getAttribute(DeliveryRequestAttributes.CORRELATION_ID);p.setStatus(s.value());p.setContentType(MediaType.APPLICATION_JSON_VALUE);p.setHeader(CorrelationHeaders.CORRELATION_ID,id);mapper.writeValue(p.getOutputStream(),new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),c.name(),message,q.getRequestURI(),id,List.of()));}}
